interface FirstStageDeflexProcessedTransaction {
  txn: algosdk.Transaction
  needsUserSignature: boolean
  deflexSignature?: FirstStageDeflexTransactionSignature
  originalGroupId?: Uint8Array
}

export interface FirstStagePeraQuote {
  id: number;
  quote_id_str: string;
  asset_in_id: number;
  asset_out_id: number;
  amount: string;
  amount_out: string;
  exchange_fee_amount: string;
  taxedAmount: number;
  minReceived?: number;
  fromAssetInfo: AssetInformation | null;
  toAssetInfo: AssetInformation | null;
}

export interface FirstStageDeflexQuote {
  quote: string | number;
  profit: { amount: number; asa: { id: number } };
  priceBaseline: number;
  route: {
    percentage: number;
    path: { name: string; in: { id: number }; out: { id: number } }[];
  }[];
  quotes: { name: string; value: string }[];
  requiredAppOptIns: number[];
  txnPayload: Record<string, string> | null;
  protocolFees: { [key: string]: number };
  flattenedRoute: { [key: string]: number };
  fromAPIResponse?: any;
}

const DEFAULT_APP_IDS = {
  testnet: 743789179,
  mainnet: 3158291365,
};

const DEFAULT_LP_APP_IDS = {
  testnet: 743764650n,
  mainnet: 3155594055n,
};


export class FirstStageSDK {
  private algod: Algodv2;
  private algodConfig: { token: string; server: string; port: string };
  private appId: number;
  private algorandClient: AlgorandClient;
  private baseClient?: BaseClient;
  private fsClient: FirstStageClient;
  private lpClient: LpDepositClient;
  private network: "mainnet" | "testnet";

  public get clientParams() {
    return this.fsClient?.params;
  }

  public get clientAppId() {
    return this.fsClient?.appId;
  }

  constructor(
    network: "testnet" | "mainnet" = "testnet",
    algodConfig?: { token: string; server: string; port: string }
  ) {
    this.network = network;
    this.appId = DEFAULT_APP_IDS[network];

    const server =
      network === "mainnet"
        ? "https://mainnet-api.algonode.cloud"
        : "https://testnet-api.algonode.cloud";

    this.algod = algodConfig
      ? new algosdk.Algodv2(algodConfig.token, algodConfig.server, algodConfig.port)
      : new algosdk.Algodv2("", server, "");

    this.algodConfig = {
      token: algodConfig?.token ?? "",
      server: algodConfig?.server ?? server,
      port: algodConfig?.port ?? "",
    };

    this.algod = new algosdk.Algodv2(
      this.algodConfig.token,
      this.algodConfig.server,
      this.algodConfig.port
    );

    this.algorandClient = AlgorandClient.fromConfig({
      algodConfig: {
        token: algodConfig?.token ?? "",
        server: algodConfig?.server ?? server,
        port: algodConfig?.port ?? "",
      },
    });

this.fsClient = new FirstStageClient({
  appId: this.appId,
  algorand: this.algorandClient,
  defaultSigner: algosdk.makeEmptyTransactionSigner(),
});
this.lpClient = new LpDepositClient({
  appId: DEFAULT_LP_APP_IDS[network],
  algorand: this.algorandClient,
  defaultSigner: algosdk.makeEmptyTransactionSigner(),
});
  }

    public getAlgod(): Algodv2 {
    return this.algod;
  }

async getAssetInformation(assetId: number): Promise<AssetInformation | null> {
  try {
    const key = getBoxKeyForAsset(assetId);
    const res = await this.algod.getApplicationBoxByName(this.appId, key).do();
    return decodeAssetBox(new Uint8Array(res.value));
  } catch (err: any) {
    if (err?.message?.includes("box not found") || err?.statusCode === 404) {
      return null;
    }
    console.error(`Error fetching asset box: ${err}`);
    return null;
  }
}

  async getUserInformation(assetId: number, userAddress: string): Promise<Uint8Array | null> {
    try {
      const key = getUserAssetBoxKey(assetId, userAddress);
      const res = await this.algod.getApplicationBoxByName(this.appId, key).do();
      return new Uint8Array(res.value);
    } catch {
      return null;
    }
  }

async isFreezeEligible(address: string, assetId: number): Promise<boolean> {
  const exemptResult = await this.fsClient.checkIsAddressExempt({
    sender: address,
    args: [address, BigInt(assetId)]
  });

  if (exemptResult === true) {
    return false;
  }

  const maybeExemptAppResult = await this.fsClient.checkIsAddressMaybeExemptApp({
    sender: address,
    args: [address, BigInt(assetId)]
  });

  if (maybeExemptAppResult === true) {
    return false;
  }

  return true;
}

  async getUserAssetInfo(assetId: number, userAddress: string): Promise<UserAssetInfo | null> {
    try {
      const userBox = await this.getUserInformation(assetId, userAddress);
      if (!userBox) return null;

      const view = new DataView(userBox.buffer);
      const readUint64BE = (offset: number) => {
        const high = view.getUint32(offset, false);
        const low = view.getUint32(offset + 4, false);
        return BigInt(high) * BigInt(2 ** 32) + BigInt(low);
      };

      const claimable_freeze_rewards = readUint64BE(32);
      const registered_balance = readUint64BE(40);
      this.baseClient = new BaseClient(this.fsClient, this.lpClient, this.algorandClient, userAddress);

      const [pending_reflections_tokens, pending_reflections_algo] =
        await this.baseClient.client.getReflectionPreview({
          sender: userAddress,
          args: [BigInt(assetId), userAddress],
        });

      return {
        claimable_freeze_rewards,
        registered_balance,
        pending_reflections_tokens,
        pending_reflections_algo,
      };
    } catch (err) {
      console.error(`Failed to fetch user asset info: ${err}`);
      return null;
    }
  }
async fetchDeflexQuoteWithTax({
  fromAssetId,
  toAssetId,
  amount,
  type = "fixed-input",
  disabledProtocols = [],
  feeBps,
  deflexReferrerAddress,
  network = "mainnet",
  deflexApiUrl,
  deflexApiKey,
  algodToken,
  algodServer,
  algodPort,
  slippage = 0.005,
  maxGroupSize = 16,
}: {
  fromAssetId: number;
  toAssetId: number;
  amount: number;
  type?: "fixed-input" | "fixed-output";
  disabledProtocols?: string[];
  feeBps?: number;
  deflexReferrerAddress?: string; 
  network?: "mainnet" | "testnet";
  deflexApiUrl?: string;
  deflexApiKey?: string;
  algodToken?: string;
  algodServer?: string;
  algodPort?: string | number;
  slippage?: number;
  maxGroupSize?: number;
}): Promise<FirstStageDeflexQuote> {

  const fromAssetInfo = await this.getAssetInformation(fromAssetId);
  const toAssetInfo = await this.getAssetInformation(toAssetId);

  let taxedAmount = amount;
  let minReceived: number | undefined;

  if (fromAssetInfo?.sell_tax && fromAssetInfo.total_tax_bps) {
    taxedAmount = Math.floor(amount * (1 - Number(fromAssetInfo.total_tax_bps) / 10_000));
  }

  if (toAssetInfo?.buy_tax && toAssetInfo.total_tax_bps && type === "fixed-input") {
    minReceived = Math.floor(amount * (1 - Number(toAssetInfo.total_tax_bps) / 10_000));
  }

let groupSize: number;
if (fromAssetInfo && toAssetInfo) {
  groupSize = 10;
} else if (fromAssetInfo || toAssetInfo) {
  groupSize = 13;
} else {
  groupSize = maxGroupSize;
}

  const server = algodServer ?? this.algodConfig.server;
  const token = algodToken ?? this.algodConfig.token;
  const port = algodPort ?? this.algodConfig.port;
  const baseUrl = deflexApiUrl ?? process.env.EXPO_PUBLIC_DEFLEX_API_URL ?? "https://deflex.txnlab.dev";

  const url = new URL(`${baseUrl}/api/fetchQuote`);
  url.searchParams.append("chain", network);
  url.searchParams.append("algodUri", server);
  url.searchParams.append("algodToken", token);
  url.searchParams.append("algodPort", port.toString());
  url.searchParams.append("fromASAID", fromAssetId.toString());
  url.searchParams.append("toASAID", toAssetId.toString());
  url.searchParams.append("amount", taxedAmount.toString());
  url.searchParams.append("type", type);
  url.searchParams.append("atomicOnly", "true");
  url.searchParams.append("disabledProtocols", disabledProtocols.join(","));
  url.searchParams.append("slippage", slippage.toString());
  url.searchParams.append("maxGroupSize", groupSize.toString());

  const key = deflexApiKey ?? process.env.EXPO_PUBLIC_DEFLEX_API_KEY;
  if (key) url.searchParams.append("apiKey", key);

  if (feeBps !== undefined) url.searchParams.append("feeBps", feeBps.toString());
  if (deflexReferrerAddress) url.searchParams.append("referrerAddress", deflexReferrerAddress);
  if (minReceived !== undefined) url.searchParams.append("minReceived", minReceived.toString());

  console.log({
    fromAssetId,
    toAssetId,
    fromAssetInfo,
    toAssetInfo,
    taxedAmount,
    minReceived,
    groupSize,
    url: url.toString()
  });

  const response = await fetch(url.toString());
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Failed to fetch Deflex quote: ${response.status} ${response.statusText} - ${errorText}`);
  }

  const quote = (await response.json()) as any;
  return quote as FirstStageDeflexQuote;
}

async generateGeneralOpsGroup(
  userAddress: string,
  assetIds: number[],
  userTxns: UserTxnWithSigner[],
  referralAddress: string,
  defaultSigner?: algosdk.TransactionSigner
): Promise<TransactionComposer> {
  const suggestedParams = await this.algod.getTransactionParams().do();
  const composer: TransactionComposer = this.fsClient.algorand.newGroup();
  const fallbackSigner: algosdk.TransactionSigner = defaultSigner ?? algosdk.makeEmptyTransactionSigner();

  const signerAccount = { addr: userAddress, signer: fallbackSigner };

  for (const assetId of assetIds) {
    const assetInfo = await FirstStageSDK.fetchAssetInfo(assetId, "mainnet");
    if (!assetInfo) throw new Error(`Asset info not found for asset ${assetId}`);
    const totalTaxBps = assetInfo.total_tax_bps ?? 0;
    console.log(`Asset ${assetId}: totalTaxBps=${totalTaxBps}`);

    const userInfo = await this.getUserAssetInfo(assetId, userAddress);
    const initialBalance = userInfo?.registered_balance ?? 0n;

    let netChange = 0n;
    for (const { txn } of userTxns) {
      if (txn.type === "axfer") {
        const axfer = txn as any;
        const txAssetId = BigInt(axfer.assetTransfer?.assetIndex ?? 0n);
        const amt = BigInt(axfer.assetTransfer?.amount ?? 0n);

        if (txAssetId === BigInt(assetId)) {
          if (axfer.sender && axfer.sender.toString() === userAddress) netChange -= amt;
          if (axfer.assetTransfer?.receiver && axfer.assetTransfer.receiver.toString() === userAddress)
            netChange += amt;
        }

        console.log(`UserTx: assetId=${txAssetId}, amount=${amt}, sender=${axfer.sender}, receiver=${axfer.assetTransfer?.receiver}`);
      }
    }
    console.log(`Computed netChange=${netChange} for asset ${assetId}`);

function computeContractTax(amountTransferred: bigint, totalTaxBps: bigint): bigint {
  // Solve t = ceil((amountTransferred + t) * totalTaxBps / 10_000)
  // => t * 10_000 >= (amountTransferred + t) * totalTaxBps
  // => t * (10_000 - totalTaxBps) >= amountTransferred * totalTaxBps
  return (amountTransferred * totalTaxBps + (10_000n - totalTaxBps) - 1n) / (10_000n - totalTaxBps);
}
const absChange = netChange < 0n ? -netChange : netChange;
const taxAmount = computeContractTax(absChange, BigInt(totalTaxBps));

    const freezeEligible = await this.isFreezeEligible(userAddress, assetId);

    if (!freezeEligible) {
      console.log(`User is freeze-exempt for asset ${assetId}, skipping top/bottom/tax`);
    }

    if (freezeEligible) {
      const topTxn = await this.fsClient.params.generalOperationsTop({
        sender: userAddress,
        args: [1n, BigInt(assetId), initialBalance],
        extraFee: AlgoAmount.MicroAlgos(2000),
        signer: signerAccount.signer,
      });
      composer.addAppCallMethodCall(topTxn);
    }

    for (const { txn, signer } of userTxns) {
      const txSigner = signer ? { addr: userAddress, signer } : signerAccount;
      composer.addTransaction(txn, txSigner.signer);
    }

    if (freezeEligible) {
      const taxTxn = algosdk.makeAssetTransferTxnWithSuggestedParamsFromObject({
        sender: userAddress,
        receiver: this.fsClient.appAddress,
        assetIndex: assetId,
        amount: taxAmount,
        suggestedParams,
      });

      const bottomTxn = await this.fsClient.params.generalOperationsBottom({
        sender: userAddress,
        args: [
          2n,
          BigInt(assetId),
          { txn: taxTxn, signer: signerAccount.signer },
          referralAddress,
        ],
        signer: signerAccount.signer,
        extraFee: AlgoAmount.MicroAlgos(11000),
      });
      composer.addAppCallMethodCall(bottomTxn);
    }
  }

  return composer;
}

  async generateDeflexSwapGroup(
    quote: FirstStageDeflexQuote,
    userAddress: string,
    referralAddress: string,
    fromAssetId: number,
    toAssetId: number,
    slippage = 0.005,
    defaultSigner?: algosdk.TransactionSigner,
    apiKey?: string
  ): Promise<TransactionComposer> {
  if (!quote?.txnPayload) {
    throw new Error("Deflex quote returned no txnPayload");
  }

  const executionResponse = await fetch("https://deflex.txnlab.dev/api/fetchExecuteSwapTxns", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      address: userAddress,
      txnPayloadJSON: quote.txnPayload,
      slippage,
      apiKey: apiKey ?? process.env.EXPO_PUBLIC_DEFLEX_API_KEY,
    }),
  });

  if (!executionResponse.ok) {
    throw new Error(`fetchExecuteSwapTxns failed: ${executionResponse.statusText}`);
  }

  const apiResponse = await executionResponse.json() as FirstStageSwapTxnsResponse;
  const deflexTxns = apiResponse.txns.map((t) => FirstStageDeflexTransaction.fromApiResponse(t));

  const processedTxns: FirstStageDeflexProcessedTransaction[] = [];
  for (const deflexTxn of deflexTxns) {
    const txnBytes = Buffer.from(deflexTxn.data, "base64");
    const transaction = algosdk.decodeUnsignedTransaction(txnBytes);
    const originalGroupId = transaction.group;
    delete transaction.group;

    if (deflexTxn.signature !== false) {
      processedTxns.push({
        txn: transaction,
        needsUserSignature: false,
        deflexSignature: deflexTxn.signature as FirstStageDeflexTransactionSignature,
        originalGroupId: originalGroupId ?? new Uint8Array(),
      });
    } else {
      processedTxns.push({
        txn: transaction,
        needsUserSignature: true,
        originalGroupId: originalGroupId ?? new Uint8Array(),
      });
    }
  }

async function reSignTransaction(transaction: algosdk.Transaction, signature: FirstStageDeflexTransactionSignature): Promise<Uint8Array> {
  try {
    if (signature.type === 'logic_signature') {
      const decoded = algosdk.msgpackRawDecode(signature.value) as any
      if (!decoded.lsig) {
        throw new Error('Logic signature structure missing lsig field')
      }
      const lsig = decoded.lsig
      const logicSigAccount = new algosdk.LogicSigAccount(lsig.l, lsig.arg)

      const signedTxn = algosdk.signLogicSigTransactionObject(transaction, logicSigAccount)
      return signedTxn.blob
    } else if (signature.type === 'secret_key') {
      const signResult = algosdk.signTransaction(transaction, signature.value)
      return signResult.blob
    } else {
      throw new Error(`Unsupported signature type: ${signature.type}`)
    }
  } catch (error) {
    console.error(`Error re-signing transaction:`, error)
    throw error
  }
}

function makeDeflexTransactionSigner(deflexSignature: FirstStageDeflexTransactionSignature): algosdk.TransactionSigner {
  return async (txnGroup: algosdk.Transaction[], indexesToSign: number[]) => {
    const signedTxns: Uint8Array[] = [];
    for (const idx of indexesToSign) {
      const txn = txnGroup[idx];
      if (!txn) {
        throw new Error(`Transaction at index ${idx} is undefined`);
      }
      const signedTxnBlob = await reSignTransaction(txn, deflexSignature);
      signedTxns.push(signedTxnBlob);
    }
    return signedTxns;
  };
}

const userTxns: UserTxnWithSigner[] = processedTxns.map((proc) => {
  if (proc.needsUserSignature) {
    return { txn: proc.txn, signer: defaultSigner! };
  } else if (proc.deflexSignature) {
    return {
      txn: proc.txn,
      signer: makeDeflexTransactionSigner(proc.deflexSignature)
    };
  } else {
    // fallback (shouldn’t happen)
    return { txn: proc.txn, signer: algosdk.makeEmptyTransactionSigner() };
  }
});

const assetIds: number[] = [];

for (const id of [fromAssetId, toAssetId]) {
  const assetInfo = await FirstStageSDK.fetchAssetInfo(id, "mainnet");
  if (assetInfo && await this.isFreezeEligible(userAddress, id)) {
    assetIds.push(id);
  }
}

const composer = await this.generateGeneralOpsGroup(
  userAddress,
  assetIds,
  userTxns,
  referralAddress,
  defaultSigner
);

return composer;
}

async fetchPeraQuoteWithTax({
  fromAssetId,
  toAssetId,
  amount,
  userAddress,
  slippage = 0.005,
  providers = ["tinyman", "vestige-v4"], // default values
}: {
  fromAssetId: number;
  toAssetId: number;
  amount: number;
  userAddress: string;
  slippage?: number;
  providers?: SwapProvider[];
}) {
  const peraSwap = new PeraSwap(this.network);

  const fromAssetInfo = await this.getAssetInformation(fromAssetId);
  const toAssetInfo = await this.getAssetInformation(toAssetId);

  let taxedAmount = amount;
  let minReceived: number | undefined;

  if (fromAssetInfo?.sell_tax && fromAssetInfo.total_tax_bps) {
    taxedAmount = Math.floor(amount * (1 - Number(fromAssetInfo.total_tax_bps) / 10_000));
  }

  if (toAssetInfo?.buy_tax && toAssetInfo.total_tax_bps) {
    minReceived = Math.floor(amount * (1 - Number(toAssetInfo.total_tax_bps) / 10_000));
  }

  const quote = await peraSwap.createQuote({
    providers,
    swapper_address: userAddress,
    swap_type: "fixed-input",
    asset_in_id: fromAssetId,
    asset_out_id: toAssetId,
    amount: taxedAmount.toString(),
    slippage: slippage.toString(),
  });

  if (!quote?.results?.length) {
    throw new Error("No Pera swap quotes found");
  }

  const best = quote.results[0];

  return {
    ...best,
    taxedAmount,
    minReceived,
    fromAssetInfo,
    toAssetInfo,
  };
}

async generatePeraSwapGroup(
  userAddress: string,
  fromAssetId: number,
  toAssetId: number,
  amount: number,
  referralAddress: string,
  slippage = 0.005,
  providers: ("tinyman" | "vestige-v4")[] = ["tinyman", "vestige-v4"],
  defaultSigner?: algosdk.TransactionSigner
): Promise<TransactionComposer> {
  const peraSwap = new PeraSwap(this.network);

  // --- Fetch asset info & apply taxes ---
  const fromAssetInfo = await this.getAssetInformation(fromAssetId);
  const toAssetInfo = await this.getAssetInformation(toAssetId);

  let taxedAmount = amount;
  let minReceived: number | undefined;

  if (fromAssetInfo?.sell_tax && fromAssetInfo.total_tax_bps) {
    taxedAmount = Math.floor(amount * (1 - Number(fromAssetInfo.total_tax_bps) / 10_000));
  }
  if (toAssetInfo?.buy_tax && toAssetInfo.total_tax_bps) {
    minReceived = Math.floor(amount * (1 - Number(toAssetInfo.total_tax_bps) / 10_000));
  }

  // --- Fetch PeraSwap quote ---
  const quoteResponse = await peraSwap.createQuote({
    providers,
    swapper_address: userAddress,
    swap_type: "fixed-input",
    asset_in_id: fromAssetId,
    asset_out_id: toAssetId,
    amount: taxedAmount.toString(),
    slippage: slippage.toString(),
  });
  if (!quoteResponse.results?.length) throw new Error("No Pera swap quotes found");
  const bestQuote = quoteResponse.results[0]!;

  // --- Prepare transactions ---
  const prepared = await peraSwap.prepareTransactions(bestQuote.quote_id_str);

  // --- Helper: re-sign a transaction ---
  async function reSignTransaction(
    txn: algosdk.Transaction,
    signature: any
  ): Promise<Uint8Array> {
    if (!signature) return algosdk.signTransaction(txn, defaultSigner! as any).blob;

    if (signature.type === "logic_signature") {
      const decoded = algosdk.msgpackRawDecode(signature.value) as any;
      const lsig = decoded.lsig;
      const logicSigAccount = new algosdk.LogicSigAccount(lsig.l, lsig.arg);
      return algosdk.signLogicSigTransactionObject(txn, logicSigAccount).blob;
    } else if (signature.type === "secret_key") {
      return algosdk.signTransaction(txn, signature.value).blob;
    } else {
      throw new Error(`Unsupported signature type: ${signature.type}`);
    }
  }

  // --- Helper: create signer for a transaction ---
  function makeTransactionSigner(signature: any): algosdk.TransactionSigner {
    return async (txnGroup: algosdk.Transaction[], indexesToSign: number[]) => {
      const signedTxns: Uint8Array[] = [];
      for (const idx of indexesToSign) {
        const txn = txnGroup[idx];
        if (!txn) throw new Error(`Transaction at index ${idx} is undefined`);
        signedTxns.push(await reSignTransaction(txn, signature));
      }
      return signedTxns;
    };
  }

  // --- Decode transactions & assign signer ---
  const userTxns: { txn: algosdk.Transaction; signer: algosdk.TransactionSigner }[] = [];

  for (const group of prepared.transaction_groups) {
    const txns: { txn: algosdk.Transaction; signer: algosdk.TransactionSigner }[] = [];

    for (const txnBase64 of group.transactions) {
      const txn = algosdk.decodeUnsignedTransaction(Buffer.from(txnBase64, "base64"));
      delete txn.group;
      const signature = (group as any).signatures?.[txn.txID()] ?? null;

      const signer: algosdk.TransactionSigner =
        signature ? makeTransactionSigner(signature) : defaultSigner ?? algosdk.makeEmptyTransactionSigner();

      txns.push({ txn, signer });
    }

    userTxns.push(...txns);
  }

  // --- Determine freeze-eligible assets for tax handling ---
  const assetIds: number[] = [];
  for (const id of [fromAssetId, toAssetId]) {
    const assetInfo = await FirstStageSDK.fetchAssetInfo(id, "mainnet");
    if (assetInfo && (await this.isFreezeEligible(userAddress, id))) {
      assetIds.push(id);
    }
  }

  // --- Generate the final TransactionComposer ---
  const composer = await this.generateGeneralOpsGroup(
    userAddress,
    assetIds,
    userTxns,
    referralAddress,
    defaultSigner
  );

  return composer;
}


async generateAddLiquidityGroup(
  userAddress: string,
  assetIds: number[],
  lpAssetId: number,
  lpAppId: number,
  userTxns: UserTxnWithSigner[],
  depositAmounts: Map<number, bigint>,
  defaultSigner?: algosdk.TransactionSigner
): Promise<TransactionComposer> {
  const suggestedParams = await this.algod.getTransactionParams().do();
  const composer: TransactionComposer = this.fsClient.algorand.newGroup();
  const fallbackSigner = defaultSigner ?? algosdk.makeEmptyTransactionSigner();
  const signerAccount = { addr: userAddress, signer: fallbackSigner };

  // --- Check if LP deposit box already exists ---
  const existingDeposit = await this.getUserDeposit(userAddress, lpAssetId);
  const mbrAmount = existingDeposit?.lp_deposit && existingDeposit.lp_deposit > 0n ? 0 : 37_700;

  for (const assetId of assetIds) {
    const userBox = await this.getUserInformation(assetId, userAddress);
    const freezeEligible = await this.isFreezeEligible(userAddress, assetId);

    if (!userBox && freezeEligible) {
      const acctInfo = await this.algod.accountInformation(userAddress).do();
      const balance = (aid: number): bigint => {
        if (aid === 0) return BigInt(acctInfo.amount);
        const asset = acctInfo.assets?.find((a: any) => a["asset-id"] === aid);
        return asset ? BigInt(asset.amount) : 0n;
      };

      const topCall = await this.fsClient.params.liquidityTop({
        sender: userAddress,
        signer: signerAccount.signer,
        args: [
          7n,
          BigInt(assetId),
          BigInt(lpAssetId),
          balance(assetId),
          balance(lpAssetId),
        ],
        extraFee: AlgoAmount.MicroAlgos(3000),
      });
      composer.addAppCallMethodCall(topCall);
    }
  }

  for (const { txn, signer } of userTxns) {
    const txSigner = signer ? { addr: userAddress, signer } : signerAccount;
    composer.addTransaction(txn, txSigner.signer);
  }

  const paymentTxn = algosdk.makePaymentTxnWithSuggestedParamsFromObject({
    sender: userAddress,
    receiver: this.lpClient.appAddress,
    amount: mbrAmount,
    suggestedParams,
  });

  if (assetIds.length === 1) {
    const assetId = assetIds[0]!;
    const amount = depositAmounts.get(assetId);
    if (amount === undefined) throw new Error(`Missing deposit amount for ${assetId}`);

    const depositTxn = algosdk.makeAssetTransferTxnWithSuggestedParamsFromObject({
      sender: userAddress,
      receiver: this.lpClient.appAddress,
      assetIndex: assetId,
      amount,
      suggestedParams,
    });

    const depositCall = await this.lpClient.params.lpDeposit({
      sender: userAddress,
      signer: signerAccount.signer,
      args: [
        BigInt(assetId),
        BigInt(lpAssetId),
        BigInt(lpAppId),
        depositTxn,
        paymentTxn,
      ],
      extraFee: AlgoAmount.MicroAlgos(9000),
    });
    composer.addAppCallMethodCall(depositCall);

  } else if (assetIds.length === 2) {
    const a1 = assetIds[0]!;
    const a2 = assetIds[1]!;

    const amt1 = depositAmounts.get(a1);
    const amt2 = depositAmounts.get(a2);
    if (amt1 === undefined || amt2 === undefined) {
      throw new Error(`Missing deposit amounts for ${a1} or ${a2}`);
    }

    const txn1 = algosdk.makeAssetTransferTxnWithSuggestedParamsFromObject({
      sender: userAddress,
      receiver: this.lpClient.appAddress,
      assetIndex: a1,
      amount: amt1,
      suggestedParams,
    });
    const txn2 = algosdk.makeAssetTransferTxnWithSuggestedParamsFromObject({
      sender: userAddress,
      receiver: this.lpClient.appAddress,
      assetIndex: a2,
      amount: amt2,
      suggestedParams,
    });

    const dualCall = await this.lpClient.params.dualLpDeposit({
      sender: userAddress,
      signer: signerAccount.signer,
      args: [
        BigInt(a1),
        BigInt(a2),
        BigInt(lpAssetId),
        BigInt(lpAppId),
        txn1,
        txn2,
        paymentTxn,
      ],
      extraFee: AlgoAmount.MicroAlgos(3000),
    });
    composer.addAppCallMethodCall(dualCall);
  }

  for (const assetId of assetIds) {
    const userBox = await this.getUserInformation(assetId, userAddress);
    const freezeEligible = await this.isFreezeEligible(userAddress, assetId);

    if (!userBox && freezeEligible) {
      const bottomCall = await this.fsClient.params.liquidityBottom({
        sender: userAddress,
        signer: signerAccount.signer,
        args: [8n, BigInt(assetId)],
        extraFee: AlgoAmount.MicroAlgos(3000),
      });
      composer.addAppCallMethodCall(bottomCall);
    }
  }

  return composer;
}

async generateRemoveLiquidityGroup(
  userAddress: string,
  assetIds: number[],
  lpAssetId: number,
  userTxns: UserTxnWithSigner[],    
  defaultSigner?: algosdk.TransactionSigner
): Promise<TransactionComposer> {
  const suggestedParams = await this.algod.getTransactionParams().do();
  const composer: TransactionComposer = this.fsClient.algorand.newGroup();
  const fallbackSigner = defaultSigner ?? algosdk.makeEmptyTransactionSigner();
  const signerAccount = { addr: userAddress, signer: fallbackSigner };

  for (const assetId of assetIds) {
    const userBox = await this.getUserInformation(assetId, userAddress);
    const freezeEligible = await this.isFreezeEligible(userAddress, assetId);

    if (!userBox && freezeEligible) {
      const acctInfo = await this.algod.accountInformation(userAddress).do();
      const balance = (aid: number): bigint => {
        if (aid === 0) return BigInt(acctInfo.amount);
        const asset = acctInfo.assets?.find((a: any) => a["asset-id"] === aid);
        return asset ? BigInt(asset.amount) : 0n;
      };

      const topCall = await this.fsClient.params.liquidityTop({
        sender: userAddress,
        signer: signerAccount.signer,
        args: [
          9n,
          BigInt(assetId),
          BigInt(lpAssetId),
          balance(assetId),
          balance(lpAssetId),
        ],
        extraFee: AlgoAmount.MicroAlgos(3000),
      });
      composer.addAppCallMethodCall(topCall);
    }
  }

  for (const { txn, signer } of userTxns) {
    const txSigner = signer ? { addr: userAddress, signer } : signerAccount;
    composer.addTransaction(txn, txSigner.signer);
  }

  const assetId = assetIds[0]!;
  const withdrawCall = await this.lpClient.params.lpWithdraw({
    sender: userAddress,
    signer: signerAccount.signer,
    args: [
      BigInt(assetId),
      BigInt(lpAssetId),
    ],
    extraFee: AlgoAmount.MicroAlgos(3000),
  });
  composer.addAppCallMethodCall(withdrawCall);

  for (const assetId of assetIds) {
    const userBox = await this.getUserInformation(assetId, userAddress);
    const freezeEligible = await this.isFreezeEligible(userAddress, assetId);

    if (!userBox && freezeEligible) {
      const bottomCall = await this.fsClient.params.liquidityBottom({
        sender: userAddress,
        signer: signerAccount.signer,
        args: [10n, BigInt(assetId)],
        extraFee: AlgoAmount.MicroAlgos(3000),
      });
      composer.addAppCallMethodCall(bottomCall);
    }
  }

  return composer;
}

 async getUserDeposit(
  userAddress: string,
  lpAssetId: number
): Promise<UserDepositInfo> {
  try {
    const addrBytes = algosdk.decodeAddress(userAddress).publicKey;
    const assetBytes = new Uint8Array(8);
    new DataView(assetBytes.buffer).setBigUint64(0, BigInt(lpAssetId), false);

    const boxKey = new Uint8Array(addrBytes.length + assetBytes.length);
    boxKey.set(addrBytes, 0);
    boxKey.set(assetBytes, addrBytes.length);

    const box = await this.algod.getApplicationBoxByName(this.lpClient.appId, boxKey).do();

    if (!box?.value) throw new Error("Box not found");

    return decodeUserDepositBox(new Uint8Array(box.value));
  } catch (err) {
    console.warn(
      `User deposit box not found for ${userAddress}, lpAssetId ${lpAssetId}:`,
      err
    );
    return {
      locked_asset_id: 0n,
      lp_deposit: 0n,
      locked_lp_tokens: 0n,
      lp_app_id: 0n,
      second_locked_asset_id: 0n,
      second_lp_deposit: 0n,
    };
  }
}

async generateFreezeTxnGroup(
  userAddress: string,
  assetId: number,
  refreezeAddress: string,
  signer?: algosdk.TransactionSigner
): Promise<TransactionComposer | null> {
  const isExempt = await this.fsClient.checkIsAddressExempt({
    sender: userAddress,
    args: [refreezeAddress, BigInt(assetId)],
  });

  if (isExempt) {
    console.log(
      `User ${refreezeAddress} IS on whitelist (exempt) → cannot be frozen for asset ${assetId}.`
    );
    return null;
  }

  console.log(
    `User ${userAddress} is NOT exempt → freeze-eligible candidate for asset ${assetId}.`
  );

  const composer = this.fsClient.algorand.newGroup();
  const defaultSigner = signer ?? algosdk.makeEmptyTransactionSigner();

  let isMaybeExempt = false;
  try {
    isMaybeExempt = await this.fsClient.checkIsAddressMaybeExemptApp({
      sender: userAddress,
      args: [refreezeAddress, BigInt(assetId)],
    });
  } catch {
    isMaybeExempt = false;
  }

  const paymentAmount = isMaybeExempt ? 10_000_000 : 37_700;
  console.log(
    `Payment amount determined: ${paymentAmount} microAlgos (maybeExempt=${isMaybeExempt})`
  );

  const suggestedParams = await this.algod.getTransactionParams().do();
  const paymentTxn = algosdk.makePaymentTxnWithSuggestedParamsFromObject({
    sender: userAddress,
    receiver: this.fsClient.appAddress,
    amount: paymentAmount,
    suggestedParams,
  });

  const freezeMethod = this.fsClient.params.freeze;
  const args: [
    bigint,
    string | Uint8Array,
    { txn: algosdk.Transaction; signer: algosdk.TransactionSigner }
  ] = [
    BigInt(assetId),
    refreezeAddress ?? "",
    { txn: paymentTxn, signer: defaultSigner },
  ];

  const freezeTxn = await freezeMethod({
    sender: userAddress,
    signer: defaultSigner,
    onComplete: algosdk.OnApplicationComplete.NoOpOC,
    args,
    extraFee: AlgoAmount.MicroAlgos(3000),
  });

  composer.addAppCallMethodCall(freezeTxn);

  return composer;
}


  static async fetchAssetInfo(
    assetId: number,
    network: "testnet" | "mainnet" = "testnet",
    algodConfig?: { token: string; server: string; port: string }
  ): Promise<AssetInformation | null> {
    const applicationId = DEFAULT_APP_IDS[network];

    const server =
      network === "mainnet"
        ? "https://mainnet-api.algonode.cloud"
        : "https://testnet-api.algonode.cloud";

    const algod = algodConfig
      ? new algosdk.Algodv2(algodConfig.token, algodConfig.server, algodConfig.port)
      : new algosdk.Algodv2("", server, "");

    try {
      const key = getBoxKeyForAsset(assetId);
      const res = await algod.getApplicationBoxByName(applicationId, key).do();
      return decodeAssetBox(new Uint8Array(res.value));
    } catch (err) {
      console.warn(`Could not fetch asset info for assetId=${assetId}: ${err}`);
      return null;
    }
  }
}
